hl.window_rule({
    name = "confine-steam-games",
    match = {
        class = "^(steam_app_).*$",
    },
    confine_pointer = true,
})

hl.window_rule({
    name = "confine-source-games",
    match = {
        class = "^(hl2_linux|cstrike_linux64|csgo_linux64|portal2_linux|left4dead2_linux)$",
    },
    confine_pointer = true,
})

hl.workspace_rule({
    workspace = "w[tv1]",
    gaps_in = 0,
    gaps_out = 0,
})

-- Smart gaps: no gaps/border/rounding when a workspace has exactly one tiled
-- window. floating:0 ensures floating windows (e.g. a PiP video) on the same
-- workspace are never touched.
hl.window_rule({
    name = "smart-gaps-borders",
    match = {
        float = false,
        workspace = "w[tv1]",
    },
    border_size = 0,
})

hl.window_rule({
    name = "smart-gaps-rounding",
    match = {
        float = false,
        workspace = "w[tv1]",
    },
    rounding = 0,
})

-- Picture-in-a-Picture (PIP) rules
hl.window_rule({
    name = "pip",
    match = {
        title = "^(Picture-in-Picture)$",
    },
    opacity = "1.0 1.0",
    pin = true,
    float = true,
    size = "17.8% 24%",
    move = "72% 7%",
})

